#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=10
cd "$(dirname "${BASH_SOURCE[0]}")/.."
REPO_DIR="$PWD"
ENV_FILE="$HOME/.config/mzk/setup.env"
mkdir -p "$(dirname "$ENV_FILE")"
APP_REPO="mzk-composer"
DATA_REPO="muzeka-composicoes"
DATA_DIR="$HOME/Muzeka/composicoes"
SERVER_PID=""
trap '[[ -n "$SERVER_PID" ]] && kill "$SERVER_PID" 2>/dev/null; true' EXIT

banner "MZK Composer · GitHub, iPhone e sincronização"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "Programas necessários"
if command -v gh >/dev/null 2>&1 && command -v qrencode >/dev/null 2>&1; then
  say "gh (GitHub no terminal) e qrencode (QR code) já estão instalados. ✓"
else
  say "Vou instalar dois programas pequenos:"
  step "gh — conversa com o GitHub pelo terminal"
  step "qrencode — mostra um QR code para abrir o app no iPhone"
  note "O Linux vai pedir a sua senha de usuário (é normal, não aparece enquanto digita)."
  if confirm "Instalar agora (sudo apt install gh qrencode)?"; then
    sudo apt-get update -qq && sudo apt-get install -y gh qrencode
  else
    warn "Sem o gh o assistente não consegue continuar."; exit 1
  fi
fi
pause "Enter para continuar"

# ── 2 ────────────────────────────────────────────────────────────────────
stage "Entrar no GitHub"
if gh auth status >/dev/null 2>&1; then
  say "Você já está conectado ao GitHub neste computador. ✓"
else
  say "O terminal vai mostrar um código de 8 letras e abrir o navegador."
  step "No navegador, entre na sua conta (pode ser 'Continue with Google')."
  step "Cole o código que aparece aqui no terminal e autorize."
  note "Se perguntar 'Authenticate Git with your GitHub credentials?', responda Y."
  pause "Enter para começar"
  gh auth login --hostname github.com --git-protocol https --web
fi
gh auth setup-git >/dev/null 2>&1 || true
GH_USER="$(gh api user -q .login)"
write_env GH_USER "$GH_USER"
say "Conta: $GH_USER"
pause "Enter para continuar"

# ── 3 ────────────────────────────────────────────────────────────────────
stage "Seu nome nas versões salvas"
if [[ -n "$(git config --global user.name || true)" ]]; then
  say "O git já sabe seu nome: $(git config --global user.name) ✓"
else
  say "Cada versão salva no GitHub leva um nome de autor."
  ask GIT_NAME "Seu nome (ex.: Léo Santos):"
  git config --global user.name "$GIT_NAME"
  write_env GIT_NAME "$GIT_NAME"
fi
if [[ -z "$(git config --global user.email || true)" ]]; then
  GH_ID="$(gh api user -q .id)"
  git config --global user.email "${GH_ID}+${GH_USER}@users.noreply.github.com"
  note "E-mail das versões: o endereço 'noreply' do GitHub (seu e-mail real não fica público)."
fi
pause "Enter para continuar"

# ── 4 ────────────────────────────────────────────────────────────────────
stage "Publicar o app (repositório público: só o código)"
say "O app vai para https://github.com/$GH_USER/$APP_REPO — público, mas só com o"
say "código do programa. Suas músicas NUNCA vão para lá (elas vão para o privado)."
note "Atenção: o projeto de exemplo (examples/) leva o nome 'Leo Santos' como compositor."
if gh repo view "$GH_USER/$APP_REPO" >/dev/null 2>&1 && git -C "$REPO_DIR" remote get-url origin >/dev/null 2>&1; then
  say "Repositório já existe. Enviando as últimas mudanças…"
  git add -A
  git diff --cached --quiet || git commit -q -m "Atualiza MZK Composer"
  git push -q origin main
else
  if ! confirm "Criar o repositório público e enviar o código?"; then warn "Pulei. Rode de novo quando quiser."; exit 1; fi
  [[ -d .git ]] || git init -q -b main
  git add -A
  git diff --cached --quiet || git commit -q -m "MZK Composer: núcleo, app, PWA offline e sincronização

Co-Authored-By: Claude Opus 5.5 <noreply@anthropic.com>"
  if gh repo view "$GH_USER/$APP_REPO" >/dev/null 2>&1; then
    git remote add origin "https://github.com/$GH_USER/$APP_REPO.git" 2>/dev/null || true
    git push -q -u origin main
  else
    gh repo create "$APP_REPO" --public --source . --remote origin --push \
      --description "Caderno de rascunhos musicais da Muzeka (PWA)"
  fi
fi
say "Código publicado. ✓"
pause "Enter para continuar"

# ── 5 ────────────────────────────────────────────────────────────────────
stage "Ligar o GitHub Pages (endereço do app com HTTPS)"
if ! gh api "repos/$GH_USER/$APP_REPO/pages" >/dev/null 2>&1; then
  gh api -X POST "repos/$GH_USER/$APP_REPO/pages" -f 'source[branch]=main' -f 'source[path]=/' >/dev/null
fi
APP_URL="$(gh api "repos/$GH_USER/$APP_REPO/pages" -q .html_url)"
write_env APP_URL "$APP_URL"
say "Endereço do app: $APP_URL"
say "Esperando o GitHub publicar (costuma levar 1–2 minutos)…"
for _ in $(seq 1 40); do
  code="$(curl -s -o /dev/null -w '%{http_code}' "${APP_URL}index.html" || true)"
  [[ "$code" == "200" ]] && break
  sleep 5
done
if [[ "${code:-}" == "200" ]]; then say "No ar! ✓"; else warn "Ainda não respondeu; pode levar mais uns minutos. Seguimos."; fi
pause "Enter para continuar"

# ── 6 ────────────────────────────────────────────────────────────────────
stage "Repositório PRIVADO das composições"
if gh repo view "$GH_USER/$DATA_REPO" >/dev/null 2>&1; then
  say "github.com/$GH_USER/$DATA_REPO já existe. ✓"
else
  gh repo create "$DATA_REPO" --private --add-readme \
    --description "Composições da Muzeka (MZK Composer) — privado"
  say "Criado: github.com/$GH_USER/$DATA_REPO (privado) ✓"
fi
if [[ -d "$DATA_DIR/.git" ]]; then
  say "Cópia no computador: $DATA_DIR ✓"
else
  mkdir -p "$(dirname "$DATA_DIR")"
  gh repo clone "$GH_USER/$DATA_REPO" "$DATA_DIR" -- -q
  say "Cópia no computador: $DATA_DIR ✓"
fi
note "É dessa pasta que o ./mzk build vai ler os projetos."
pause "Enter para continuar"

# ── 7 ────────────────────────────────────────────────────────────────────
stage "Chave de acesso deste computador"
say "Vou abrir a página do GitHub já preenchida. Lá:"
step "Confira 'Resource owner' = $GH_USER e 'Expiration' = 366 days."
step "Em 'Repository access', escolha 'Only select repositories'."
step "No menu 'Select repositories', marque $DATA_REPO (só ele)."
step "Em 'Permissions', confira 'Contents' = Read and write (já vem assim)."
step "Clique em 'Generate token' (e confirme) e copie a chave (começa com github_pat_)."
open_url "https://github.com/settings/personal-access-tokens/new?name=MZK+Composer+-+computador&description=Sincronizar+composicoes+do+MZK+Composer&target_name=${GH_USER}&expires_in=366&contents=write"
while true; do
  ask_secret PAT "Cole a chave aqui para eu testar (não aparece na tela):"
  code="$(curl -s -o /dev/null -w '%{http_code}' -H "Authorization: Bearer $PAT" \
    "https://api.github.com/repos/$GH_USER/$DATA_REPO/contents/README.md" || true)"
  if [[ "$code" == "200" ]]; then say "Chave funcionando. ✓"; break; fi
  warn "A chave não abriu o $DATA_REPO (código $code). Confira o passo 'Only select repositories' e cole de novo."
done
printf '%s' "$PAT" | xclip -selection clipboard 2>/dev/null && note "A chave ficou copiada (Ctrl+V) para o próximo passo."
pause "Enter para continuar"

# ── 8 ────────────────────────────────────────────────────────────────────
stage "Conectar o app neste computador"
say "O 'From Now On' está guardado no app de http://localhost:8080. Primeiro ele"
say "sobe para a nuvem; depois a versão publicada (HTTPS) recebe tudo."
if ! curl -s -o /dev/null "http://localhost:8080/"; then
  ./mzk serve --port 8080 >/dev/null 2>&1 &
  SERVER_PID=$!
  sleep 1
fi
open_url "http://localhost:8080/"
step "Aperte F5. Vá na aba Projeto → 'Sincronizar com o GitHub'."
step "Repositório privado: $GH_USER/$DATA_REPO"
step "Chave: Ctrl+V → Conectar. Deve aparecer 'Conectado! … enviado(s)'."
pause "Enter quando aparecer 'Conectado'"
say "Projetos na nuvem agora:"
gh api "repos/$GH_USER/$DATA_REPO/contents/projects" -q '.[].name' 2>/dev/null | sed 's/^/    /' || warn "ainda nada em projects/ — confira se apareceu 'Conectado'."
open_url "$APP_URL"
step "Esta é a versão publicada. Projeto → 'Sincronizar com o GitHub' → mesmos dados (Ctrl+V) → Conectar."
step "Em 'Meus projetos' deve aparecer o From Now On."
note "Daqui em diante, no computador use este endereço (salve nos favoritos): $APP_URL"
pause "Enter quando o From Now On aparecer"
printf '' | xclip -selection clipboard 2>/dev/null || true
unset PAT

# ── 9 ────────────────────────────────────────────────────────────────────
stage "iPhone: instalar e conectar"
say "Aponte a câmera do iPhone para o QR code e toque no link (abre no Safari):"
qrencode -t ANSIUTF8 -m 1 "$APP_URL" 2>/dev/null | sed 's/^/    /' || say "$APP_URL"
step "No Safari: Compartilhar (quadrado com seta) → 'Adicionar à Tela de Início' → Adicionar."
step "Feche o Safari e abra o app pelo ícone MZK na tela inicial (importante: pelo ícone)."
step "Aba Projeto → 'Sincronizar com o GitHub' → Repositório: $GH_USER/$DATA_REPO"
step "Toque em 'Criar chave no GitHub' → entre na conta → 'Only select repositories' → $DATA_REPO"
step "'Generate token' → copie a chave → volte ao app MZK → cole → Conectar."
step "Em 'Meus projetos' do iPhone deve aparecer o From Now On."
note "Cada aparelho tem sua própria chave: se perder o iPhone, apague só a chave dele no GitHub."
pause "Enter quando o iPhone mostrar o From Now On"

# ── 10 ───────────────────────────────────────────────────────────────────
stage "Teste final: iPhone → computador"
step "No iPhone, mude algo no From Now On (ex.: uma nota) e toque na nuvem verde no topo."
say "Depois, no computador, um comando busca a versão nova e gera MIDI + partitura:"
say "    ./mzk build MZK-0001"
if confirm "Rodar agora?"; then
  ./mzk build MZK-0001 || warn "Não deu — confira se o iPhone sincronizou e tente de novo."
fi
note "A chave vence em 1 ano: rode este assistente de novo (ele pula o que já está pronto)."

finish
}

run_wizard "$@"; exit
